        S(305),
        S(21)
    ):AddToggle(false, function(state)
        autoMine.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(113),
        S(65)
    ):AddToggle(false, function(state)
        autoPlace.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(264),
        S(40)
    ):AddToggle(false, function(state)
        autoChest.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(156),
        S(173)
    ):AddToggle(false, function(state)
        autoSell.SetEnabled(state)
    end)
    farmTab:AddCard(
        S(67),
        S(101)
    ):AddToggle(false, function(state)
        autoUpgrade.SetEnabled(state)
    end)
    local debugCard = farmTab:AddCard(S(56), S(278))
    local checkBtn
    checkBtn = debugCard:AddButton(S(32), function()
        local plot = getCurrentPlot()
        if not plot then
            checkBtn.Text = S(208)
            log(S(300))
            return
        end
        local parts = getPlotParts(plot)
        local nodeCount = parts.Nodes and #parts.Nodes:GetChildren() or 0
        local holderCount = parts.Holders and #parts.Holders:GetChildren() or 0
        checkBtn.Text = plot.Name
        log(string.format(
            S(127),
            plot.Name, nodeCount, holderCount
        ))
    end)
    local dumpCard = farmTab:AddCard(
        S(151),
        S(138)
    )
    local dumpBtn
    dumpBtn = dumpCard:AddButton(S(100), function()
        local plot = getCurrentPlot()
        if not plot then
            dumpBtn.Text = S(270)
            return
        end
        local ok, err = log(S(147))
        if not ok then
            dumpBtn.Text = S(266)
            dumpCard:SetSubtitle(S(224) .. tostring(err))
            return
        end
        local parts = getPlotParts(plot)
        local firstNode = parts.Nodes and parts.Nodes:GetChildren()[1]
        if firstNode then
            log(S(91) .. firstNode.Name .. S(49))
            dumpInstance(firstNode, log)
        else
            log(S(97))
        end
        local firstHolder = parts.Holders and parts.Holders:GetChildren()[1]
        if firstHolder then
            log(S(12) .. firstHolder.Name .. S(263))
            dumpInstance(firstHolder, log)
        else
            log(S(244))
        end
        dumpBtn.Text = S(205)
    end)
    local toolDumpCard = farmTab:AddCard(
        S(176),
        S(76)
    )
    local toolDumpBtn
    toolDumpBtn = toolDumpCard:AddButton(S(89), function()
        local backpack = Players.LocalPlayer:FindFirstChild(S(268))
        local tool = backpack and backpack:FindFirstChildWhichIsA(S(309))
        if not tool then
            toolDumpBtn.Text = S(172)
            return
        end
        log(S(11) .. tool.Name .. S(121))
        for attrName, attrValue in pairs(tool:GetAttributes()) do
            log(S(265) .. attrName .. S(78) .. tostring(attrValue))
        end
        dumpInstance(tool, log)
        toolDumpBtn.Text = S(64)
    end)
    local remoteDumpCard = farmTab:AddCard(
        S(112),
        S(239)
    )
    local remoteDumpBtn
    remoteDumpBtn = remoteDumpCard:AddButton(S(35), function()
        local count = dumpRemotes()
        remoteDumpBtn.Text = count .. S(227)
    end)
    local settingsTab = window:AddTab(S(75), S(59))
    settingsTab:AddCard(S(155), S(58)):AddToggle(false, function(state)
        antiAfk.SetEnabled(state)
    end)
    settingsTab:AddCard(
        S(60),
        S(167)
    ):AddToggle(false, function(state)
        interactionLogger.SetEnabled(state)
    end)
    settingsTab:AddSlider(S(132), S(150), 50, 150, 100, function(value)
        window:SetScale(value)
    end)
    settingsTab:AddSegmented({ S(216), S(139), S(82) }, 1, function(index, value)
        local code = ({ S(250), S(279), S(241) })[index]
        i18n.SetLanguage(code)
    end)
    window:OnDestroy(function()
        autoMine.SetEnabled(false)
        autoPlace.SetEnabled(false)
        autoChest.SetEnabled(false)
        antiAfk.SetEnabled(false)
        interactionLogger.SetEnabled(false)
        autoSell.SetEnabled(false)
        autoUpgrade.SetEnabled(false)
    end)
end
